package com.nextrade.domain.ledger; import com.nextrade.common.enumtype.LedgerEntryType; import com.nextrade.common.identifier.*; import com.nextrade.common.valueobject.*; public record Tax(LedgerEntry entry) { public Tax { if(entry.type()!=LedgerEntryType.TAX) throw new IllegalArgumentException("Wrong ledger type"); } public static Tax of(UserId user,Money amount,String reference){ return new Tax(new LedgerEntry(LedgerEntryId.generate(),user,LedgerEntryType.TAX,amount,reference,java.time.Instant.now())); } }